//
//  PLYMesh.swift
//  MabelTeleop
//
//  Minimal PLY → RealityKit MeshResource loader for the MABEL rig parts
//  (Resources/MabelRig/*.ply, Resources/NovaRig/*.ply — trimesh exports:
//  binary_little_endian, vertices = float x,y,z [+ uchar r,g,b,a], faces =
//  uchar count + int32 indices [+ uchar r,g,b,a]). The rig manifest supplies
//  a single colour per part, so colours are ignored; normals are generated by
//  RealityKit. Colour may sit on the vertex OR the face element (the NovaRig
//  exports put it on the face): the face record size comes from the header,
//  never assumed — assuming `1 + n*4` misread every NOVA face as garbage and
//  a negative index trapped `UInt32(_:)` on launch (2026-10-14).
//

import Foundation
import RealityKit
import simd

enum PLYMesh {

    struct Geometry {
        var positions: [SIMD3<Float>]
        var indices: [UInt32]
    }

    /// Parse a binary-little-endian PLY (the only flavour the rig uses).
    static func parse(url: URL) -> Geometry? {
        guard let data = try? Data(contentsOf: url) else { return nil }

        // ── Header (ASCII up to "end_header\n") ─────────────────────────────
        guard let headerEnd = data.range(of: Data("end_header\n".utf8)) else { return nil }
        guard let header = String(data: data[..<headerEnd.lowerBound], encoding: .ascii) else { return nil }

        func size(_ t: String) -> Int {
            switch t {
            case "float", "float32", "int", "int32", "uint", "uint32": return 4
            case "double", "float64": return 8
            case "short", "ushort", "int16", "uint16": return 2
            default: return 1          // char / uchar
            }
        }

        var vertexCount = 0, faceCount = 0
        var vertexProps: [(name: String, bytes: Int)] = []
        // Face record: [pre bytes] count index×n [post bytes].
        var facePre = 0, facePost = 0, faceCountBytes = 1, faceIndexBytes = 4
        var faceListSeen = false
        var element = ""
        for line in header.split(separator: "\n") {
            let parts = line.split(separator: " ").map(String.init)
            guard !parts.isEmpty else { continue }
            switch parts[0] {
            case "format":
                guard parts.count > 1, parts[1] == "binary_little_endian" else { return nil }
            case "element":
                guard parts.count >= 3 else { return nil }
                element = parts[1]
                if element == "vertex" { vertexCount = Int(parts[2]) ?? 0 }
                if element == "face" { faceCount = Int(parts[2]) ?? 0 }
            case "property":
                if element == "vertex", parts.count >= 3 {
                    vertexProps.append((parts[2], size(parts[1])))
                } else if element == "face" {
                    if parts.count >= 5, parts[1] == "list" {
                        faceCountBytes = size(parts[2]); faceIndexBytes = size(parts[3])
                        faceListSeen = true
                    } else if parts.count >= 3 {
                        if faceListSeen { facePost += size(parts[1]) } else { facePre += size(parts[1]) }
                    }
                }
            default: break
            }
        }
        guard vertexCount > 0, faceCountBytes == 1,
              faceIndexBytes == 4 || faceIndexBytes == 2 else { return nil }

        let stride = vertexProps.reduce(0) { $0 + $1.bytes }
        var xOff = -1, yOff = -1, zOff = -1
        var off = 0
        for p in vertexProps {
            if p.name == "x" { xOff = off }
            if p.name == "y" { yOff = off }
            if p.name == "z" { zOff = off }
            off += p.bytes
        }
        guard xOff >= 0, yOff >= 0, zOff >= 0 else { return nil }

        let body = data[headerEnd.upperBound...]
        let needed = vertexCount * stride
        guard body.count >= needed else { return nil }

        var positions = [SIMD3<Float>](repeating: .zero, count: vertexCount)
        var indices: [UInt32] = []
        indices.reserveCapacity(faceCount * 3)

        body.withUnsafeBytes { (raw: UnsafeRawBufferPointer) in
            let base = raw.baseAddress!
            for v in 0..<vertexCount {
                let p = base + v * stride
                let x = p.loadUnaligned(fromByteOffset: xOff, as: Float.self)
                let y = p.loadUnaligned(fromByteOffset: yOff, as: Float.self)
                let z = p.loadUnaligned(fromByteOffset: zOff, as: Float.self)
                positions[v] = SIMD3(x, y, z)
            }
            // Faces: [pre] uchar n + n × index [post]. Triangulate fans for
            // n > 3. An out-of-range index drops that face, never traps — a
            // bad asset must cost one part, not the whole app.
            let ib = faceIndexBytes
            func index(_ at: Int) -> UInt32? {
                let i = ib == 4 ? Int(base.loadUnaligned(fromByteOffset: at, as: Int32.self))
                                : Int(base.loadUnaligned(fromByteOffset: at, as: UInt16.self))
                return (0..<vertexCount).contains(i) ? UInt32(i) : nil
            }
            var o = vertexCount * stride
            for _ in 0..<faceCount {
                o += facePre
                guard o < raw.count else { break }
                let n = Int(base.loadUnaligned(fromByteOffset: o, as: UInt8.self)); o += 1
                let end = o + n * ib
                guard end + facePost <= raw.count else { break }
                defer { o = end + facePost }
                guard n >= 3, let i0 = index(o) else { continue }
                for k in 1..<(n - 1) {
                    guard let i1 = index(o + k * ib), let i2 = index(o + (k + 1) * ib) else { continue }
                    indices.append(contentsOf: [i0, i1, i2])
                }
            }
        }
        return Geometry(positions: positions, indices: indices)
    }

    /// Build a MeshResource from parsed geometry (normals auto-generated).
    static func meshResource(from g: Geometry) throws -> MeshResource {
        var desc = MeshDescriptor()
        desc.positions = MeshBuffer(g.positions)
        desc.primitives = .triangles(g.indices)
        return try MeshResource.generate(from: [desc])
    }
}
